//! Gate clause 4, board-crate half: the committed `boards/sentinel-01` is
//! exactly what the generator writes for `examples/sentinel-01-minimal.json`,
//! every byte of every file, the Kani harness included. That is what guards
//! the harness (`INV-07`, ruled on PR #42, R3): a hand edit fails here.
//!
//! The tree also holds the reference firmware under `firmware/` and the
//! twin's `sentinel-01.repl` (`AET-WO-2100`, R1 and R6), so every committed
//! generated byte is checked. The firmware's constants are cross-checked
//! against the judge's, which `aethelgard-twin` writes independently.
//!
//! `AETHELGARD_BLESS=1 cargo test -p aethelgard-svd-hal --test board` writes
//! the tree instead of comparing it; nothing else ever writes `boards/`.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use aethelgard_cli::generate;
use aethelgard_ir::Specification;
use aethelgard_svd_hal::pin_table;
use sha2::{Digest, Sha256};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn board_dir() -> PathBuf {
    root().join("boards/sentinel-01")
}

/// The `board/` part of what `aethelgard generate` writes, through the one
/// composition function the CLI uses (`AET-WO-3301` §1.5).
fn generated() -> BTreeMap<String, String> {
    let bytes = fs::read(root().join("examples/sentinel-01-minimal.json")).unwrap();
    let spec: Specification = serde_json::from_slice(&bytes).unwrap();
    let sha: String = Sha256::digest(&bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    let table = pin_table(&spec.mcu.part).unwrap();
    let solved = aethelgard_ir::solve(&spec, &table, &sha).unwrap();
    let prefix = format!("{}/", generate::BOARD_DIR);
    generate::tree(&spec, &solved, &table)
        .unwrap()
        .into_iter()
        .filter_map(|(path, text)| Some((path.strip_prefix(&prefix)?.to_owned(), text)))
        .collect()
}

/// Every regular file under `dir`, relative, with `/` separators. `target/`
/// at the top is skipped (a local build of the crate); anything else that is
/// not a regular file is reported as a difference by [`compare`].
fn tree(dir: &Path) -> BTreeMap<String, Vec<u8>> {
    let mut out = BTreeMap::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(d) = stack.pop() {
        for entry in fs::read_dir(&d).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            let rel = path
                .strip_prefix(dir)
                .unwrap()
                .to_str()
                .unwrap()
                .replace('\\', "/");
            let kind = entry.file_type().unwrap();
            if kind.is_dir() {
                if rel != "target" {
                    stack.push(path);
                }
            } else if kind.is_file() {
                out.insert(rel, fs::read(&path).unwrap());
            } else {
                out.insert(rel, b"<not a regular file>".to_vec());
            }
        }
    }
    out
}

/// The files that differ between `dir` and `files`, missing and extra ones
/// included. Empty means byte-identical.
fn compare(dir: &Path, files: &BTreeMap<String, String>) -> Vec<String> {
    let on_disk = tree(dir);
    let mut diffs = Vec::new();
    for (path, text) in files {
        match on_disk.get(path) {
            None => diffs.push(format!("missing: {path}")),
            Some(bytes) if bytes != text.as_bytes() => diffs.push(format!("differs: {path}")),
            Some(_) => {}
        }
    }
    for path in on_disk.keys() {
        if !files.contains_key(path) {
            diffs.push(format!("extra: {path}"));
        }
    }
    diffs
}

#[test]
fn the_committed_board_crate_is_exactly_the_generated_one() {
    let files = generated();
    if std::env::var_os("AETHELGARD_BLESS").is_some() {
        let dir = board_dir();
        if dir.exists() {
            fs::remove_dir_all(&dir).unwrap();
        }
        for (path, text) in &files {
            let p = dir.join(path);
            fs::create_dir_all(p.parent().unwrap()).unwrap();
            fs::write(p, text).unwrap();
        }
    }
    assert_eq!(compare(&board_dir(), &files), Vec::<String>::new());
}

#[test]
fn two_generations_are_byte_identical() {
    assert_eq!(generated(), generated());
}

/// The negative control: a copy of the committed tree with one oracle
/// assertion weakened, the firmware edited or the platform edited is caught,
/// and so are an extra and a missing file.
#[test]
fn a_hand_edited_harness_fails_the_comparison() {
    let files = generated();
    let copy = std::env::temp_dir().join(format!("aet-1400-board-{}", std::process::id()));
    let _ = fs::remove_dir_all(&copy);
    for (path, bytes) in tree(&board_dir()) {
        let p = copy.join(&path);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, bytes).unwrap();
    }
    assert_eq!(compare(&copy, &files), Vec::<String>::new());

    let proofs = copy.join("src/proofs.rs");
    let text = fs::read_to_string(&proofs).unwrap();
    let weakened = text.replacen("kani::assert(", "kani::cover!(", 1);
    assert_ne!(text, weakened);
    fs::write(&proofs, weakened).unwrap();
    assert_eq!(compare(&copy, &files), ["differs: src/proofs.rs"]);

    fs::write(&proofs, &text).unwrap();

    // A hand edit of the firmware or of the platform is caught too.
    for (path, from, to) in [
        ("firmware/src/main.rs", "spin_loop", "nop"),
        ("sentinel-01.repl", "sysbus 0x40013000", "sysbus 0x40013004"),
    ] {
        let file = copy.join(path);
        let text = fs::read_to_string(&file).unwrap();
        let edited = text.replacen(from, to, 1);
        assert_ne!(text, edited, "{path}");
        fs::write(&file, edited).unwrap();
        assert_eq!(compare(&copy, &files), [format!("differs: {path}")]);
        fs::write(&file, text).unwrap();
    }

    fs::write(copy.join("src/extra.rs"), "").unwrap();
    fs::remove_file(copy.join("Cargo.lock")).unwrap();
    assert_eq!(
        compare(&copy, &files),
        ["missing: Cargo.lock", "extra: src/extra.rs"]
    );
    fs::remove_dir_all(&copy).unwrap();
}

/// The generator and the judge are written independently; these are the two
/// numbers they must agree on (R1, R2): the magic the firmware writes and the
/// address it writes it to.
#[test]
fn the_firmware_follows_the_judges_boot_contract() {
    let files = generated();
    let main = &files["firmware/src/main.rs"];
    let magic = format!("{:#010x}", aethelgard_twin::boot::BOOT_MAGIC);
    assert!(
        main.contains(&format!("const BOOT_MAGIC: u32 = {magic};")),
        "{magic}"
    );
    let ram = format!(
        "ORIGIN = {:#010x}",
        aethelgard_twin::boot::boot_word().unwrap()
    );
    let link = &files["firmware/link.x"];
    assert!(link.contains(&format!("RAM   : {ram},")), "{ram}");
    assert!(link.contains("*(.aethelgard_boot)"));
    // Nothing else of the firmware's reaches the host or another crate.
    assert!(!files["firmware/Cargo.toml"].contains("build ="));
    assert!(!files.contains_key("firmware/build.rs"));
}

/// `AET-WO-2202`, `AET-WO-4200`: the record layout and the statuses are
/// written twice, by the firmware's generator and by the judge,
/// independently. They must agree, and the firmware must read exactly the
/// devices the judge will check, in its record order.
#[test]
fn the_firmware_follows_the_judges_record_layout() {
    use aethelgard_twin::boot::{
        RECORD_BYTES, RECORD_OFFSET, RECORD_UNSET, STATUS_OK, STATUS_RXNE, STATUS_RXP, STATUS_STOP,
        STATUS_TC, STATUS_TXIS, Wire,
    };
    let files = generated();
    let main = &files["firmware/src/main.rs"];
    for (name, v) in [
        ("STATUS_OK", STATUS_OK),
        ("STATUS_TXIS", STATUS_TXIS),
        ("STATUS_TC", STATUS_TC),
        ("STATUS_RXNE", STATUS_RXNE),
        ("STATUS_STOP", STATUS_STOP),
        ("STATUS_RXP", STATUS_RXP),
        ("RECORD_UNSET", RECORD_UNSET),
    ] {
        assert!(
            main.contains(&format!("const {name}: u32 = {v:#010x};")),
            "{name}"
        );
    }
    // The array holds the boot word, then one record per read: the BME280's
    // and the flash's.
    let words = (RECORD_OFFSET + 2 * RECORD_BYTES) / 4;
    assert!(
        main.contains(&format!(
            "static mut AETHELGARD_BOOT: [u32; {words}] = [0; {words}];"
        )),
        "two reads: {words} words"
    );
    assert!(main.contains(&format!(
        "base.add({} + {} * index)",
        RECORD_OFFSET / 4,
        RECORD_BYTES / 4
    )));
    assert!(main.contains(&format!(
        "base.add({} + {} * index)",
        RECORD_OFFSET / 4 + 1,
        RECORD_BYTES / 4
    )));

    // Exactly the judge's checks are read, each into its own record, in the
    // judge's order: the BME280 at 0x76 (register 0xD0, one byte), then the
    // W25Q64JV behind PA0 (0x9F, three bytes); the TMP117 is unmodelled and
    // has no read.
    let bytes = fs::read(root().join("examples/sentinel-01-minimal.json")).unwrap();
    let spec: Specification = serde_json::from_slice(&bytes).unwrap();
    let sha: String = Sha256::digest(&bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    let table = pin_table(&spec.mcu.part).unwrap();
    let solved = aethelgard_ir::solve(&spec, &table, &sha).unwrap();
    let plan = aethelgard_twin::boot::identity(&solved).unwrap();
    let wires: Vec<&Wire> = plan.checks.iter().map(|c| &c.wire).collect();
    assert!(
        matches!(wires.as_slice(), [Wire::I2c { .. }, Wire::Spi { .. }]),
        "{wires:?}"
    );
    assert_eq!(plan.unmodelled.len(), 1);
    let mut at = 0;
    for (k, c) in plan.checks.iter().enumerate() {
        let bus = c.peripheral.to_ascii_lowercase();
        let to = match &c.wire {
            Wire::I2c { address } => format!("{address:#04x}"),
            // The bus's device enum, and the reference upper-cased.
            Wire::Spi { .. } => format!(
                "Spi{}Device::{}",
                &c.peripheral[3..],
                c.reference.to_ascii_uppercase()
            ),
        };
        let read = format!(
            "    let mut buf{k} = [0u8; {w}];\n    \
             let (status, value) = match {bus}.transfer(&mut r, {to}, &[{reg:#04x}], &mut buf{k}) {{",
            w = c.width,
            reg = c.write,
        );
        let start = main[at..]
            .find(&read)
            .unwrap_or_else(|| panic!("check {k} is not read in order: {read}\n{main}"))
            + at;
        let record = format!("    record({k}, status, value);\n");
        at = main[start..].find(&record).unwrap() + start;
    }
    assert_eq!(main.matches(".transfer(").count(), plan.checks.len());
}
